public class Dog
{
    private string name, color;
    private int age;

    public void setValues(string name, int age, string color)
    {
        this.name = name;   // this отличает поле от параметра
        this.age = age;
        this.color = color;
    }

    public string getName() { return name; }
    public int getAge() { return age; }
}

Dog fido = new Dog();
fido.setValues("Fido", 3, "Brown");
Console.WriteLine(fido.getName());

public class Cat
{
    private string name;
    private int age;

    public Cat()                    // конструктор без аргументов
    {
        name = "Tigger";
        age = 3;
    }

    public void setName(string name) { this.name = name; }
    public string getName() { return name; }
}

Cat tigger = new Cat();   // конструктор вызван автоматически

public class Polygon
{
    protected int width, height;   // protected — видно дочерним

    public void setValues(int width, int height)
    {
        this.width = width;
        this.height = height;
    }
}

public class Rectangle : Polygon
{
    public int area() { return (width * height); }
}

public class Triangle : Polygon
{
    public int area() { return ((width * height) / 2); }
}

public class Parent
{
    public Parent() { Console.WriteLine("Parent Called"); }
    public Parent(int num) { Console.WriteLine("Parent+ : " + num); }
}

public class Son : Parent
{
    public Son() { Console.WriteLine("\tSon Called"); }

    public Son(int num) : base(num)   // явный вызов нужного конструктора
    { Console.WriteLine("\tSon+ : " + num); }
}

public class Man
{
    public void speak() { Console.Write("Hello: "); }
    public void speak(string message) { Console.WriteLine(message + "!"); }
}

public class Hombre : Man
{
    public new void speak(string message)   // скрывает метод базового
    {
        base.speak();                       // явный вызов базового
        Console.WriteLine(message);
    }
}

((Man)enrique).speak("Es una tarde hermosa");  // вызвать скрытый метод

public class Bird
{
    public virtual void talk()
    { Console.WriteLine("A Bird Talks..."); }
}

public class Pigeon : Bird
{
    public override void talk()
    { Console.WriteLine("Pigeon Says: Coo! Coo!"); }
}

static void describe(Bird obj) { obj.talk(); }
describe(new Pigeon());   // вызовет версию голубя

public abstract class Bird
{
    public abstract void talk();   // без тела: реализуют потомки
}

public sealed class Pigeon : Bird   // от него наследовать нельзя
{
    public override void talk()
    { Console.WriteLine("Coo! Coo!"); }
}

